cat <<EOF > /root/process_berkshire.py
import csv

q2_accession = "0000950123-25-008343"
q3_accession = "0001193125-25-282901"

q2_holdings = {}
q3_holdings = {}

# Read Q2
with open('/root/2025-q2/INFOTABLE.tsv', 'r') as f:
    reader = csv.reader(f, delimiter='\t')
    for row in reader:
        if row[0] == q2_accession:
            cusip = row[4]
            try:
                value = float(row[6]) # VALUE is column 7 (index 6)
            except ValueError:
                continue
            q2_holdings[cusip] = q2_holdings.get(cusip, 0) + value

# Read Q3
with open('/root/2025-q3/INFOTABLE.tsv', 'r') as f:
    reader = csv.reader(f, delimiter='\t')
    for row in reader:
        if row[0] == q3_accession:
            cusip = row[4]
            try:
                value = float(row[6])
            except ValueError:
                continue
            q3_holdings[cusip] = q3_holdings.get(cusip, 0) + value

# Calculate increase
increases = []
for cusip, val_q3 in q3_holdings.items():
    val_q2 = q2_holdings.get(cusip, 0)
    diff = val_q3 - val_q2
    if diff > 0:
        increases.append((cusip, diff))

# Sort by difference descending
increases.sort(key=lambda x: x[1], reverse=True)

# Print top 5
print([x[0] for x in increases[:5]])
EOF
